/**
 * Config plugin: turns off Xcode's user script sandboxing.
 *
 * Recent Xcode denies the React Native bundle phase its write of `ip.txt` into
 * the app bundle, which that phase does not declare as an output, and the build
 * stops. `expo-build-properties` has no option for this setting.
 *
 * ios/ is in .gitignore and regenerated by prebuild, so this has to be a plugin.
 */
const { withXcodeProject } = require('@expo/config-plugins');

function disableSandboxing(project) {
  const configs = project.pbxXCBuildConfigurationSection();
  for (const config of Object.values(configs)) {
    if (config.buildSettings) config.buildSettings.ENABLE_USER_SCRIPT_SANDBOXING = 'NO';
  }
}

module.exports = function withoutUserScriptSandboxing(config) {
  return withXcodeProject(config, (cfg) => {
    disableSandboxing(cfg.modResults);
    return cfg;
  });
};
module.exports.disableSandboxing = disableSandboxing;
